                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "use client";

/**
 * src/components/AuditoriaMode.jsx
 * ─────────────────────────────────────────────────────────────────────────────
 * Modo Auditoría — Examen de Certificación BIAN Individual
 *
 * Flujo:
 *   Pantalla Intro → Preguntas (una a una con timer) → Resultados → Certificado
 *
 * Data-Driven: consume examen_certificacion[] del JSON.
 * Para cambiar el tema basta con cambiar el JSON.
 * ─────────────────────────────────────────────────────────────────────────────
 */

import { useState, useEffect, useCallback, useRef } from "react";

// ─── Constantes ───────────────────────────────────────────────────────────────
const APROBACION_PCT = 70; // % mínimo para aprobar

// ─── Helpers ──────────────────────────────────────────────────────────────────
const fmtTime = (s) => `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

function calcScore(respuestas, preguntas) {
  let obtenido = 0;
  let maximo   = 0;
  preguntas.forEach((q) => {
    maximo += q.puntaje;
    const seleccionada = respuestas[q.id];
    if (seleccionada) {
      const opcion = q.opciones.find((o) => o.id === seleccionada);
      if (opcion?.es_correcta) obtenido += q.puntaje;
    }
  });
  return { obtenido, maximo, pct: maximo > 0 ? Math.round((obtenido / maximo) * 100) : 0 };
}

// ─── Pantalla 1: Introducción ─────────────────────────────────────────────────
function IntroScreen({ config, preguntas, playerName, onStart }) {
  const totalPts    = preguntas.reduce((s, q) => s + q.puntaje, 0);
  const totalSeg    = preguntas.reduce((s, q) => s + q.tiempo_limite_seg, 0);
  const dificultades = preguntas.reduce((acc, q) => {
    acc[q.dificultad] = (acc[q.dificultad] || 0) + 1;
    return acc;
  }, {});

  return (
    <div className="min-h-screen bg-zinc-950 flex items-center justify-center p-6">
      <div className="max-w-lg w-full space-y-8">

        {/* Header */}
        <div className="text-center space-y-2">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full border border-indigo-800 bg-indigo-950/50 text-indigo-400 text-xs font-mono mb-4">
            <span className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse" />
            MODO AUDITORÍA
          </div>
          <h1 className="text-3xl font-black text-white tracking-tight">
            Examen de Certificación
          </h1>
          <p className="text-zinc-400 text-sm">
            {config?.textos_ui?.certificado_subtitulo ?? "BIAN v14 — Modernización Bancaria"}
          </p>
        </div>

        {/* Stats del examen */}
        <div className="grid grid-cols-2 gap-3">
          {[
            ["Preguntas",   preguntas.length,    "text-white"],
            ["Puntos totales", totalPts,          "text-indigo-400"],
            ["Tiempo total", fmtTime(totalSeg),   "text-amber-400"],
            ["Mínimo para aprobar", `${APROBACION_PCT}%`, "text-emerald-400"],
          ].map(([label, val, color]) => (
            <div key={label} className="bg-zinc-900 border border-zinc-800 rounded-xl p-4">
              <p className="text-[10px] text-zinc-600 font-mono uppercase tracking-wider mb-1">{label}</p>
              <p className={`text-2xl font-bold font-mono ${color}`}>{val}</p>
            </div>
          ))}
        </div>

        {/* Distribución de dificultad */}
        <div className="bg-zinc-900 border border-zinc-800 rounded-xl p-4 space-y-2">
          <p className="text-[10px] text-zinc-600 font-mono uppercase tracking-wider">Distribución</p>
          <div className="flex gap-2 flex-wrap">
            {Object.entries(dificultades).map(([dif, n]) => {
              const cfg = {
                "FÁCIL"  : "bg-emerald-900/50 text-emerald-400 border-emerald-800",
                "MEDIA"  : "bg-amber-900/50   text-amber-400   border-amber-800",
                "ALTA"   : "bg-red-900/50     text-red-400     border-red-800",
                "EXPERTO": "bg-purple-900/50  text-purple-400  border-purple-800",
              }[dif] ?? "bg-zinc-800 text-zinc-400 border-zinc-700";
              return (
                <span key={dif} className={`text-xs px-2.5 py-1 rounded-lg border font-mono ${cfg}`}>
                  {dif} × {n}
                </span>
              );
            })}
          </div>
        </div>

        {/* Reglas */}
        <div className="space-y-1.5 text-xs text-zinc-500">
          {[
            "Cada pregunta tiene su propio temporizador — si se acaba, pasa automáticamente.",
            "No puedes volver a preguntas anteriores.",
            "Al terminar verás tu resultado detallado y la explicación de cada respuesta.",
            "Con ≥70% recibes tu certificado digital.",
          ].map((r, i) => (
            <div key={i} className="flex items-start gap-2">
              <span className="text-indigo-600 mt-0.5 shrink-0">▸</span>
              <span>{r}</span>
            </div>
          ))}
        </div>

        {/* Botón iniciar */}
        <button
          onClick={onStart}
          className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-bold text-sm tracking-wide transition-all duration-200 active:scale-[0.98] shadow-lg shadow-indigo-900/40"
        >
          Iniciar Examen →
        </button>

        {playerName && (
          <p className="text-center text-[11px] text-zinc-700">
            Candidato: <span className="text-zinc-500">{playerName}</span>
          </p>
        )}
      </div>
    </div>
  );
}

// ─── Pantalla 2: Pregunta ─────────────────────────────────────────────────────
function QuestionScreen({ pregunta, numero, total, onAnswer, timeLeft, timerPct }) {
  const [selected, setSelected] = useState(null);
  const [confirmed, setConfirmed] = useState(false);

  const handleConfirm = () => {
    if (!selected || confirmed) return;
    setConfirmed(true);
    setTimeout(() => onAnswer(selected), 600);
  };

  const isCrit = timeLeft <= 10;

  return (
    <div className="min-h-screen bg-zinc-950 flex flex-col">

      {/* Barra de progreso temporal */}
      <div className="h-1 bg-zinc-800">
        <div
          className={`h-full transition-all duration-1000 ${isCrit ? "bg-red-500" : "bg-indigo-500"}`}
          style={{ width: `${timerPct}%` }}
        />
      </div>

      {/* Header */}
      <header className="px-6 py-4 border-b border-zinc-800 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <span className="text-xs font-mono text-zinc-600">
            Pregunta <span className="text-white font-bold">{numero}</span> de {total}
          </span>
          <div className="flex gap-1">
            {Array.from({ length: total }).map((_, i) => (
              <div
                key={i}
                className={`w-1.5 h-1.5 rounded-full transition-colors ${
                  i < numero - 1 ? "bg-indigo-500" : i === numero - 1 ? "bg-white" : "bg-zinc-700"
                }`}
              />
            ))}
          </div>
        </div>

        {/* Timer */}
        <div className={`font-mono text-lg font-bold px-3 py-1 rounded-lg border transition-colors ${
          isCrit
            ? "text-red-400 border-red-800 bg-red-950/40 animate-pulse"
            : "text-zinc-300 border-zinc-700 bg-zinc-900"
        }`}>
          {fmtTime(timeLeft)}
        </div>
      </header>

      {/* Contenido */}
      <main className="flex-1 flex flex-col items-center justify-center px-6 py-8">
        <div className="max-w-2xl w-full space-y-6">

          {/* Badge de dificultad y puntos */}
          <div className="flex items-center gap-2">
            <span className={`text-[10px] px-2 py-0.5 rounded border font-mono font-bold ${
              {
                "FÁCIL"  : "bg-emerald-900/50 text-emerald-400 border-emerald-800",
                "MEDIA"  : "bg-amber-900/50   text-amber-400   border-amber-800",
                "ALTA"   : "bg-red-900/50     text-red-400     border-red-800",
                "EXPERTO": "bg-purple-900/50  text-purple-400  border-purple-800",
              }[pregunta.dificultad] ?? ""
            }`}>
              {pregunta.dificultad}
            </span>
            <span className="text-[10px] text-zinc-600 font-mono">{pregunta.puntaje} puntos</span>
          </div>

          {/* Pregunta */}
          <h2 className="text-lg font-bold text-white leading-relaxed">
            {pregunta.pregunta}
          </h2>

          {/* Opciones */}
          <div className="space-y-3">
            {pregunta.opciones.map((opcion) => {
              const isSelected = selected === opcion.id;
              return (
                <button
                  key={opcion.id}
                  onClick={() => !confirmed && setSelected(opcion.id)}
                  disabled={confirmed}
                  className={[
                    "w-full text-left px-4 py-3.5 rounded-xl border-2 transition-all duration-150",
                    "flex items-start gap-3 group",
                    confirmed
                      ? "cursor-default"
                      : "cursor-pointer hover:border-indigo-600/60 hover:bg-indigo-950/20",
                    isSelected
                      ? "border-indigo-500 bg-indigo-950/40"
                      : "border-zinc-700 bg-zinc-900/60",
                  ].join(" ")}
                >
                  {/* Letra de opción */}
                  <span className={`shrink-0 w-6 h-6 rounded-full border flex items-center justify-center text-xs font-bold font-mono transition-colors ${
                    isSelected
                      ? "border-indigo-500 bg-indigo-500 text-white"
                      : "border-zinc-600 text-zinc-500 group-hover:border-indigo-600"
                  }`}>
                    {opcion.id}
                  </span>
                  <span className={`text-sm leading-relaxed ${isSelected ? "text-white" : "text-zinc-300"}`}>
                    {opcion.texto}
                  </span>
                </button>
              );
            })}
          </div>

          {/* Botón confirmar */}
          <button
            onClick={handleConfirm}
            disabled={!selected || confirmed}
            className={`w-full py-3.5 rounded-xl font-bold text-sm transition-all duration-200 ${
              selected && !confirmed
                ? "bg-indigo-600 hover:bg-indigo-500 text-white active:scale-[0.98]"
                : "bg-zinc-800 text-zinc-600 cursor-not-allowed"
            }`}
          >
            {confirmed ? "Registrando..." : selected ? "Confirmar respuesta →" : "Selecciona una opción"}
          </button>
        </div>
      </main>
    </div>
  );
}

// ─── Pantalla 3: Resultados ───────────────────────────────────────────────────
function ResultsScreen({ preguntas, respuestas, playerName, config, onCertificate, onRetry }) {
  const { obtenido, maximo, pct } = calcScore(respuestas, preguntas);
  const aprobado = pct >= APROBACION_PCT;

  return (
    <div className="min-h-screen bg-zinc-950 text-white">

      {/* Hero resultado */}
      <div className={`px-6 py-12 text-center border-b border-zinc-800 ${
        aprobado ? "bg-emerald-950/30" : "bg-red-950/20"
      }`}>
        <div className={`text-6xl font-black font-mono mb-2 ${aprobado ? "text-emerald-400" : "text-red-400"}`}>
          {pct}%
        </div>
        <h2 className={`text-2xl font-bold mb-1 ${aprobado ? "text-emerald-300" : "text-red-300"}`}>
          {aprobado ? "¡Aprobado!" : "No aprobado"}
        </h2>
        <p className="text-zinc-400 text-sm">
          {obtenido} de {maximo} puntos · Mínimo requerido: {APROBACION_PCT}%
        </p>
        {playerName && (
          <p className="text-zinc-600 text-xs mt-1">Candidato: {playerName}</p>
        )}

        <div className="flex gap-3 justify-center mt-6">
          {aprobado && (
            <button
              onClick={onCertificate}
              className="px-6 py-2.5 bg-emerald-700 hover:bg-emerald-600 text-white rounded-xl font-bold text-sm transition-all"
            >
              Ver Certificado →
            </button>
          )}
          <button
            onClick={onRetry}
            className="px-6 py-2.5 bg-zinc-800 hover:bg-zinc-700 text-zinc-200 rounded-xl font-bold text-sm transition-all border border-zinc-700"
          >
            Reintentar
          </button>
        </div>
      </div>

      {/* Detalle pregunta a pregunta */}
      <div className="max-w-2xl mx-auto px-6 py-8 space-y-4">
        <h3 className="text-xs font-mono text-zinc-600 uppercase tracking-widest mb-4">
          Revisión de respuestas
        </h3>

        {preguntas.map((q, idx) => {
          const seleccionada  = respuestas[q.id];
          const opcionElegida = q.opciones.find((o) => o.id === seleccionada);
          const opcionCorrecta = q.opciones.find((o) => o.es_correcta);
          const esCorrecto    = opcionElegida?.es_correcta;
          const sinRespuesta  = !seleccionada;

          return (
            <div
              key={q.id}
              className={`rounded-xl border p-4 space-y-3 ${
                esCorrecto
                  ? "border-emerald-800/60 bg-emerald-950/20"
                  : "border-red-800/60 bg-red-950/10"
              }`}
            >
              {/* Header */}
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-[10px] font-mono text-zinc-600">
                      #{idx + 1} · {q.dificultad} · {q.puntaje} pts
                    </span>
                    {esCorrecto
                      ? <span className="text-[10px] text-emerald-400 font-bold">✓ Correcto +{q.puntaje}</span>
                      : <span className="text-[10px] text-red-400 font-bold">{sinRespuesta ? "⏱ Sin respuesta" : "✗ Incorrecto"}</span>
                    }
                  </div>
                  <p className="text-sm text-zinc-200 leading-relaxed">{q.pregunta}</p>
                </div>
              </div>

              {/* Respuesta elegida */}
              {!sinRespuesta && (
                <div className={`px-3 py-2 rounded-lg text-xs ${
                  esCorrecto
                    ? "bg-emerald-900/30 text-emerald-300 border border-emerald-800/40"
                    : "bg-red-900/20 text-red-300 border border-red-800/40"
                }`}>
                  <span className="font-bold mr-1">Tu respuesta ({seleccionada}):</span>
                  {opcionElegida?.texto}
                </div>
              )}

              {/* Respuesta correcta (si falló) */}
              {!esCorrecto && opcionCorrecta && (
                <div className="px-3 py-2 rounded-lg text-xs bg-emerald-900/20 text-emerald-300 border border-emerald-800/40">
                  <span className="font-bold mr-1">Respuesta correcta ({opcionCorrecta.id}):</span>
                  {opcionCorrecta.texto}
                </div>
              )}

              {/* Explicación */}
              <p className="text-xs text-zinc-500 leading-relaxed">
                {esCorrecto ? opcionElegida?.explicacion : opcionCorrecta?.explicacion}
              </p>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Pantalla 4: Certificado ──────────────────────────────────────────────────
function CertificateScreen({ playerName, pct, config, fecha }) {
  const titulo    = config?.textos_ui?.certificado_titulo    ?? "Certificado de Competencia";
  const subtitulo = config?.textos_ui?.certificado_subtitulo ?? "BIAN v14 — Modernización Bancaria";
  const version   = config?._meta?.version ?? "2.0.0";

  return (
    <div className="min-h-screen bg-zinc-950 flex flex-col items-center justify-center p-8">

      {/* Certificado */}
      <div
        id="certificado"
        className="max-w-2xl w-full bg-zinc-900 border-2 border-indigo-600 rounded-2xl p-10 space-y-6 text-center shadow-2xl shadow-indigo-900/30"
      >
        {/* Decoración superior */}
        <div className="flex items-center gap-3 justify-center">
          <div className="h-px flex-1 bg-gradient-to-r from-transparent to-indigo-700" />
          <div className="flex gap-1">
            {[...Array(5)].map((_, i) => (
              <svg key={i} className="w-4 h-4 text-indigo-500" fill="currentColor" viewBox="0 0 20 20">
                <polygon points="10,1 12.9,7 19.5,7.6 14.5,12 16.2,18.5 10,15 3.8,18.5 5.5,12 0.5,7.6 7.1,7" />
              </svg>
            ))}
          </div>
          <div className="h-px flex-1 bg-gradient-to-l from-transparent to-indigo-700" />
        </div>

        {/* Contenido */}
        <div className="space-y-1">
          <p className="text-xs text-indigo-400 font-mono uppercase tracking-[0.3em]">
            Architecture Chaos · Portafolio TIC 2026
          </p>
          <h1 className="text-3xl font-black text-white">{titulo}</h1>
          <p className="text-zinc-400 text-sm">{subtitulo}</p>
        </div>

        <div className="space-y-1 py-4 border-y border-zinc-800">
          <p className="text-xs text-zinc-600">Otorgado a</p>
          <p className="text-4xl font-black text-indigo-300 tracking-tight">
            {playerName || "Candidato"}
          </p>
        </div>

        <div className="space-y-2">
          <p className="text-sm text-zinc-400">
            Por demostrar competencia en la aplicación del estándar BIAN v14
            para la modernización de sistemas bancarios y diseño de Open APIs.
          </p>
          <div className="flex items-center justify-center gap-6 pt-2">
            <div>
              <p className="text-3xl font-black text-emerald-400">{pct}%</p>
              <p className="text-[10px] text-zinc-600 font-mono">Calificación</p>
            </div>
            <div className="w-px h-10 bg-zinc-800" />
            <div>
              <p className="text-sm font-bold text-zinc-300">{fecha}</p>
              <p className="text-[10px] text-zinc-600 font-mono">Fecha de emisión</p>
            </div>
            <div className="w-px h-10 bg-zinc-800" />
            <div>
              <p className="text-sm font-bold text-zinc-300">v{version}</p>
              <p className="text-[10px] text-zinc-600 font-mono">Config</p>
            </div>
          </div>
        </div>

        {/* Decoración inferior */}
        <div className="flex items-center gap-3 justify-center">
          <div className="h-px flex-1 bg-gradient-to-r from-transparent to-indigo-700" />
          <p className="text-[10px] text-indigo-800 font-mono">BIAN · ISO 20022 · Open Banking</p>
          <div className="h-px flex-1 bg-gradient-to-l from-transparent to-indigo-700" />
        </div>
      </div>

      {/* Acciones */}
      <div className="flex gap-3 mt-6">
        <button
          onClick={() => window.print()}
          className="px-6 py-2.5 bg-indigo-700 hover:bg-indigo-600 text-white rounded-xl font-bold text-sm transition-all"
        >
          Imprimir / Guardar PDF
        </button>
        <a
          href="/"
          className="px-6 py-2.5 bg-zinc-800 hover:bg-zinc-700 text-zinc-200 rounded-xl font-bold text-sm transition-all border border-zinc-700"
        >
          Volver al Lobby
        </a>
      </div>
    </div>
  );
}

// ─── Componente Principal ──────────────────────────────────────────────────────
export default function AuditoriaMode({ gameConfig = null, playerName = "" }) {
  const preguntas = gameConfig?.examen_certificacion ?? [];

  // Estados del flujo
  const [fase, setFase]           = useState("intro");    // intro | pregunta | resultados | certificado
  const [indice, setIndice]       = useState(0);
  const [respuestas, setRespuestas] = useState({});
  const [timeLeft, setTimeLeft]   = useState(0);
  const timerRef                  = useRef(null);

  const preguntaActual = preguntas[indice];

  // ── Timer por pregunta ──────────────────────────────────────────────────────
  useEffect(() => {
    if (fase !== "pregunta" || !preguntaActual) return;

    setTimeLeft(preguntaActual.tiempo_limite_seg);
    clearInterval(timerRef.current);

    timerRef.current = setInterval(() => {
      setTimeLeft((t) => {
        if (t <= 1) {
          clearInterval(timerRef.current);
          // Tiempo agotado → pasar sin respuesta
          handleAnswer(null);
          return 0;
        }
        return t - 1;
      });
    }, 1000);

    return () => clearInterval(timerRef.current);
  }, [fase, indice]); // eslint-disable-line

  // ── Responder pregunta ──────────────────────────────────────────────────────
  const handleAnswer = useCallback((opcionId) => {
    clearInterval(timerRef.current);

    setRespuestas((prev) => ({
      ...prev,
      ...(opcionId ? { [preguntaActual.id]: opcionId } : {}),
    }));

    const siguiente = indice + 1;
    if (siguiente >= preguntas.length) {
      setFase("resultados");
    } else {
      setIndice(siguiente);
    }
  }, [indice, preguntas.length, preguntaActual]);

  // ── Iniciar examen ──────────────────────────────────────────────────────────
  const handleStart = () => {
    setIndice(0);
    setRespuestas({});
    setFase("pregunta");
  };

  // ── Reintentar ──────────────────────────────────────────────────────────────
  const handleRetry = () => {
    setIndice(0);
    setRespuestas({});
    setFase("intro");
  };

  // ── Sin preguntas ───────────────────────────────────────────────────────────
  if (!preguntas.length) {
    return (
      <div className="min-h-screen bg-zinc-950 flex items-center justify-center">
        <p className="text-zinc-600 font-mono">No hay preguntas en el JSON.</p>
      </div>
    );
  }

  // ── Render por fase ─────────────────────────────────────────────────────────
  if (fase === "intro") {
    return (
      <IntroScreen
        config={gameConfig}
        preguntas={preguntas}
        playerName={playerName}
        onStart={handleStart}
      />
    );
  }

  if (fase === "pregunta" && preguntaActual) {
    const timerPct = (timeLeft / preguntaActual.tiempo_limite_seg) * 100;
    return (
      <QuestionScreen
        pregunta={preguntaActual}
        numero={indice + 1}
        total={preguntas.length}
        timeLeft={timeLeft}
        timerPct={timerPct}
        onAnswer={handleAnswer}
      />
    );
  }

  if (fase === "resultados") {
    const { pct } = calcScore(respuestas, preguntas);
    return (
      <ResultsScreen
        preguntas={preguntas}
        respuestas={respuestas}
        playerName={playerName}
        config={gameConfig}
        onCertificate={() => setFase("certificado")}
        onRetry={handleRetry}
      />
    );
  }

  if (fase === "certificado") {
    const { pct } = calcScore(respuestas, preguntas);
    const fecha   = new Date().toLocaleDateString("es-ES", {
      day: "numeric", month: "long", year: "numeric",
    });
    return (
      <CertificateScreen
        playerName={playerName}
        pct={pct}
        config={gameConfig}
        fecha={fecha}
      />
    );
  }

  return null;
}
